let file = """{"version":3,"file":"serverConfigStore-Bt5pVUpg.js","names":["$t","$t","$attrs","$attrs","$attrs","$t"],"sources":["../../src/components/common/BackgroundImageUpload.vue","../../src/components/common/BackgroundImageUpload.vue","../../src/components/common/CustomFormValue.vue","../../src/components/common/CustomFormValue.vue","../../src/components/common/FormColorPicker.vue","../../src/components/common/FormColorPicker.vue","../../src/components/common/FormImageUpload.vue","../../src/components/common/FormImageUpload.vue","../../src/components/common/FormNumberField.vue","../../src/components/common/FormNumberField.vue","../../src/components/common/FormRadioGroup.vue","../../src/components/common/FormRadioGroup.vue","../../src/components/ui/knob/Knob.vue","../../src/components/ui/knob/Knob.vue","../../src/components/common/InputKnob.vue","../../src/components/common/InputKnob.vue","../../src/components/common/InputSlider.vue","../../src/components/common/InputSlider.vue","../../packages/shared-frontend-utils/src/networkUtil.ts","../../src/utils/validationUtil.ts","../../src/components/common/UrlInput.vue","../../src/components/common/UrlInput.vue","../../src/components/common/FormItem.vue","../../src/components/common/FormItem.vue","../../src/stores/serverConfigStore.ts"],"sourcesContent":["<template>\n  <div class=\"flex gap-2\">\n    <Input\n      v-model=\"modelValue\"\n      class=\"flex-1\"\n      :placeholder=\"$t('g.imageUrl')\"\n    />\n    <Button\n      :tooltip=\"$t('g.upload')\"\n      variant=\"secondary\"\n      size=\"sm\"\n      :aria-label=\"$t('g.upload')\"\n      :disabled=\"isUploading\"\n      @click=\"triggerFileInput\"\n    >\n      <i :class=\"isUploading ? 'pi pi-spin pi-spinner' : 'pi pi-upload'\" />\n    </Button>\n    <Button\n      :tooltip=\"$t('g.clear')\"\n      variant=\"destructive\"\n      size=\"sm\"\n      :aria-label=\"$t('g.clear')\"\n      :disabled=\"!modelValue\"\n      @click=\"clearImage\"\n    >\n      <i class=\"pi pi-trash\" />\n    </Button>\n    <input\n      ref=\"fileInput\"\n      type=\"file\"\n      class=\"hidden\"\n      accept=\"image/*\"\n      @change=\"handleFileUpload\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport { appendCloudResParam } from '@/platform/distribution/cloudPreviewUtil'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { api } from '@/scripts/api'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nconst { t } = useI18n()\n\nconst modelValue = defineModel<string>()\n\nconst fileInput = ref<HTMLInputElement | null>(null)\nconst isUploading = ref(false)\n\nconst triggerFileInput = () => {\n  fileInput.value?.click()\n}\n\nconst uploadFile = async (file: File): Promise<string | null> => {\n  const body = new FormData()\n  body.append('image', file)\n  body.append('subfolder', 'backgrounds')\n\n  const resp = await api.fetchApi('/upload/image', {\n    method: 'POST',\n    body\n  })\n\n  if (resp.status !== 200) {\n    useToast().warning(\n      t('g.uploadFailed', { reason: `${resp.status} - ${resp.statusText}` })\n    )\n    return null\n  }\n\n  const data = await resp.json()\n  return data.subfolder ? `${data.subfolder}/${data.name}` : data.name\n}\n\nconst handleFileUpload = async (event: Event) => {\n  const target = event.target as HTMLInputElement\n  if (target.files && target.files[0]) {\n    const file = target.files[0]\n\n    isUploading.value = true\n    try {\n      const uploadedPath = await uploadFile(file)\n      if (uploadedPath) {\n        // Set the value to the API view URL with subfolder parameter\n        const params = new URLSearchParams({\n          filename: uploadedPath,\n          type: 'input',\n          subfolder: 'backgrounds'\n        })\n        appendCloudResParam(params, file.name)\n        modelValue.value = `/api/view?${params.toString()}`\n      }\n    } catch (error) {\n      useToast().warning(\n        t('g.uploadFailed', {\n          reason: getErrorMessage(error) ?? t('g.unknownError')\n        })\n      )\n    } finally {\n      isUploading.value = false\n    }\n  }\n}\n\nconst clearImage = () => {\n  modelValue.value = ''\n  if (fileInput.value) {\n    fileInput.value.value = ''\n  }\n}\n</script>\n","<template>\n  <div class=\"flex gap-2\">\n    <Input\n      v-model=\"modelValue\"\n      class=\"flex-1\"\n      :placeholder=\"$t('g.imageUrl')\"\n    />\n    <Button\n      :tooltip=\"$t('g.upload')\"\n      variant=\"secondary\"\n      size=\"sm\"\n      :aria-label=\"$t('g.upload')\"\n      :disabled=\"isUploading\"\n      @click=\"triggerFileInput\"\n    >\n      <i :class=\"isUploading ? 'pi pi-spin pi-spinner' : 'pi pi-upload'\" />\n    </Button>\n    <Button\n      :tooltip=\"$t('g.clear')\"\n      variant=\"destructive\"\n      size=\"sm\"\n      :aria-label=\"$t('g.clear')\"\n      :disabled=\"!modelValue\"\n      @click=\"clearImage\"\n    >\n      <i class=\"pi pi-trash\" />\n    </Button>\n    <input\n      ref=\"fileInput\"\n      type=\"file\"\n      class=\"hidden\"\n      accept=\"image/*\"\n      @change=\"handleFileUpload\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport { appendCloudResParam } from '@/platform/distribution/cloudPreviewUtil'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { api } from '@/scripts/api'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nconst { t } = useI18n()\n\nconst modelValue = defineModel<string>()\n\nconst fileInput = ref<HTMLInputElement | null>(null)\nconst isUploading = ref(false)\n\nconst triggerFileInput = () => {\n  fileInput.value?.click()\n}\n\nconst uploadFile = async (file: File): Promise<string | null> => {\n  const body = new FormData()\n  body.append('image', file)\n  body.append('subfolder', 'backgrounds')\n\n  const resp = await api.fetchApi('/upload/image', {\n    method: 'POST',\n    body\n  })\n\n  if (resp.status !== 200) {\n    useToast().warning(\n      t('g.uploadFailed', { reason: `${resp.status} - ${resp.statusText}` })\n    )\n    return null\n  }\n\n  const data = await resp.json()\n  return data.subfolder ? `${data.subfolder}/${data.name}` : data.name\n}\n\nconst handleFileUpload = async (event: Event) => {\n  const target = event.target as HTMLInputElement\n  if (target.files && target.files[0]) {\n    const file = target.files[0]\n\n    isUploading.value = true\n    try {\n      const uploadedPath = await uploadFile(file)\n      if (uploadedPath) {\n        // Set the value to the API view URL with subfolder parameter\n        const params = new URLSearchParams({\n          filename: uploadedPath,\n          type: 'input',\n          subfolder: 'backgrounds'\n        })\n        appendCloudResParam(params, file.name)\n        modelValue.value = `/api/view?${params.toString()}`\n      }\n    } catch (error) {\n      useToast().warning(\n        t('g.uploadFailed', {\n          reason: getErrorMessage(error) ?? t('g.unknownError')\n        })\n      )\n    } finally {\n      isUploading.value = false\n    }\n  }\n}\n\nconst clearImage = () => {\n  modelValue.value = ''\n  if (fileInput.value) {\n    fileInput.value.value = ''\n  }\n}\n</script>\n","<template>\n  <div ref=\"container\" />\n</template>\n\n<script setup lang=\"ts\">\nimport { onMounted, ref, watch } from 'vue'\n\nconst props = defineProps<{\n  renderFunction: () => HTMLElement\n}>()\n\nconst container = ref<HTMLElement | null>(null)\n\nfunction renderContent() {\n  if (container.value) {\n    container.value.innerHTML = ''\n    const element = props.renderFunction()\n    container.value.appendChild(element)\n  }\n}\n\nonMounted(renderContent)\n\nwatch(() => props.renderFunction, renderContent)\n</script>\n","<template>\n  <div ref=\"container\" />\n</template>\n\n<script setup lang=\"ts\">\nimport { onMounted, ref, watch } from 'vue'\n\nconst props = defineProps<{\n  renderFunction: () => HTMLElement\n}>()\n\nconst container = ref<HTMLElement | null>(null)\n\nfunction renderContent() {\n  if (container.value) {\n    container.value.innerHTML = ''\n    const element = props.renderFunction()\n    container.value.appendChild(element)\n  }\n}\n\nonMounted(renderContent)\n\nwatch(() => props.renderFunction, renderContent)\n</script>\n","<template>\n  <div class=\"color-picker-wrapper flex items-center gap-2\">\n    <ColorPicker\n      :id=\"id\"\n      v-model=\"hexValue\"\n      :disabled=\"disabled\"\n      :aria-labelledby=\"ariaLabelledby\"\n    />\n    <Input\n      v-model=\"draftText\"\n      class=\"w-28\"\n      :placeholder=\"label\"\n      :disabled=\"disabled\"\n      @blur=\"commitDraft\"\n      @keydown.enter=\"commitDraft\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, watch } from 'vue'\n\nimport ColorPicker from '@/components/ui/color-picker/ColorPicker.vue'\nimport Input from '@/components/ui/input/Input.vue'\n\nconst modelValue = defineModel<string>('modelValue')\nconst {\n  disabled = false,\n  id,\n  ariaLabelledby\n} = defineProps<{\n  label?: string\n  disabled?: boolean\n  id?: string\n  ariaLabelledby?: string\n}>()\n\ndefineOptions({\n  inheritAttrs: false\n})\n\n// Preserve the PrimeVue ColorPicker storage contract (hex without `#`); the\n// underlying picker uses `#`-prefixed hex, so normalize on read/write.\nconst hexValue = computed<string>({\n  get: () =>\n    modelValue.value?.startsWith('#')\n      ? modelValue.value\n      : `#${modelValue.value ?? '000000'}`,\n  set: (next) => {\n    modelValue.value = next.replace(/^#/, '')\n  }\n})\n\n// Free-text draft so partial typing (e.g. \"#f\") doesn't roundtrip through\n// the picker and snap back to black. Only commit on blur or Enter when the\n// input fully parses as 6- or 8-digit hex.\nconst draftText = ref(modelValue.value ?? '')\nwatch(modelValue, (next) => {\n  draftText.value = next ?? ''\n})\n\nconst FULL_HEX = /^#?([0-9a-f]{6}|[0-9a-f]{8})$/i\n\nfunction commitDraft() {\n  const raw = draftText.value.trim()\n  if (raw === '') {\n    draftText.value = modelValue.value ?? ''\n    return\n  }\n  if (FULL_HEX.test(raw)) {\n    modelValue.value = raw.replace(/^#/, '').toLowerCase()\n  } else {\n    draftText.value = modelValue.value ?? ''\n  }\n}\n</script>\n","<template>\n  <div class=\"color-picker-wrapper flex items-center gap-2\">\n    <ColorPicker\n      :id=\"id\"\n      v-model=\"hexValue\"\n      :disabled=\"disabled\"\n      :aria-labelledby=\"ariaLabelledby\"\n    />\n    <Input\n      v-model=\"draftText\"\n      class=\"w-28\"\n      :placeholder=\"label\"\n      :disabled=\"disabled\"\n      @blur=\"commitDraft\"\n      @keydown.enter=\"commitDraft\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, watch } from 'vue'\n\nimport ColorPicker from '@/components/ui/color-picker/ColorPicker.vue'\nimport Input from '@/components/ui/input/Input.vue'\n\nconst modelValue = defineModel<string>('modelValue')\nconst {\n  disabled = false,\n  id,\n  ariaLabelledby\n} = defineProps<{\n  label?: string\n  disabled?: boolean\n  id?: string\n  ariaLabelledby?: string\n}>()\n\ndefineOptions({\n  inheritAttrs: false\n})\n\n// Preserve the PrimeVue ColorPicker storage contract (hex without `#`); the\n// underlying picker uses `#`-prefixed hex, so normalize on read/write.\nconst hexValue = computed<string>({\n  get: () =>\n    modelValue.value?.startsWith('#')\n      ? modelValue.value\n      : `#${modelValue.value ?? '000000'}`,\n  set: (next) => {\n    modelValue.value = next.replace(/^#/, '')\n  }\n})\n\n// Free-text draft so partial typing (e.g. \"#f\") doesn't roundtrip through\n// the picker and snap back to black. Only commit on blur or Enter when the\n// input fully parses as 6- or 8-digit hex.\nconst draftText = ref(modelValue.value ?? '')\nwatch(modelValue, (next) => {\n  draftText.value = next ?? ''\n})\n\nconst FULL_HEX = /^#?([0-9a-f]{6}|[0-9a-f]{8})$/i\n\nfunction commitDraft() {\n  const raw = draftText.value.trim()\n  if (raw === '') {\n    draftText.value = modelValue.value ?? ''\n    return\n  }\n  if (FULL_HEX.test(raw)) {\n    modelValue.value = raw.replace(/^#/, '').toLowerCase()\n  } else {\n    draftText.value = modelValue.value ?? ''\n  }\n}\n</script>\n","<template>\n  <div class=\"image-upload-wrapper\">\n    <div class=\"flex items-center gap-2\">\n      <div\n        class=\"preview-box flex size-16 items-center justify-center rounded-sm border p-2\"\n        :class=\"{ 'bg-base-background': !modelValue }\"\n      >\n        <img\n          v-if=\"modelValue\"\n          :src=\"modelValue\"\n          class=\"max-h-full max-w-full object-contain\"\n        />\n        <i v-else class=\"pi pi-image text-xl text-smoke-400\" />\n      </div>\n\n      <div class=\"flex flex-col gap-2\">\n        <Button size=\"sm\" @click=\"triggerFileInput\">\n          <i class=\"pi pi-upload\" />\n          {{ $t('g.upload') }}\n        </Button>\n        <Button\n          v-if=\"modelValue\"\n          class=\"w-full\"\n          variant=\"destructive\"\n          size=\"sm\"\n          :aria-label=\"$t('g.delete')\"\n          @click=\"clearImage\"\n        >\n          <i class=\"pi pi-trash\" />\n        </Button>\n      </div>\n    </div>\n    <input\n      ref=\"fileInput\"\n      type=\"file\"\n      class=\"hidden\"\n      accept=\"image/*\"\n      @change=\"handleFileUpload\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\n\ndefineProps<{\n  modelValue: string\n}>()\n\nconst emit = defineEmits<{\n  (e: 'update:modelValue', value: string): void\n}>()\n\nconst fileInput = ref<HTMLInputElement | null>(null)\n\nconst triggerFileInput = () => {\n  fileInput.value?.click()\n}\n\nconst handleFileUpload = (event: Event) => {\n  const target = event.target as HTMLInputElement\n  if (target.files && target.files[0]) {\n    const file = target.files[0]\n    const reader = new FileReader()\n    reader.onload = (e) => {\n      emit('update:modelValue', e.target?.result as string)\n    }\n    reader.readAsDataURL(file)\n  }\n}\n\nconst clearImage = () => {\n  emit('update:modelValue', '')\n  if (fileInput.value) {\n    fileInput.value.value = ''\n  }\n}\n</script>\n","<template>\n  <div class=\"image-upload-wrapper\">\n    <div class=\"flex items-center gap-2\">\n      <div\n        class=\"preview-box flex size-16 items-center justify-center rounded-sm border p-2\"\n        :class=\"{ 'bg-base-background': !modelValue }\"\n      >\n        <img\n          v-if=\"modelValue\"\n          :src=\"modelValue\"\n          class=\"max-h-full max-w-full object-contain\"\n        />\n        <i v-else class=\"pi pi-image text-xl text-smoke-400\" />\n      </div>\n\n      <div class=\"flex flex-col gap-2\">\n        <Button size=\"sm\" @click=\"triggerFileInput\">\n          <i class=\"pi pi-upload\" />\n          {{ $t('g.upload') }}\n        </Button>\n        <Button\n          v-if=\"modelValue\"\n          class=\"w-full\"\n          variant=\"destructive\"\n          size=\"sm\"\n          :aria-label=\"$t('g.delete')\"\n          @click=\"clearImage\"\n        >\n          <i class=\"pi pi-trash\" />\n        </Button>\n      </div>\n    </div>\n    <input\n      ref=\"fileInput\"\n      type=\"file\"\n      class=\"hidden\"\n      accept=\"image/*\"\n      @change=\"handleFileUpload\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\n\ndefineProps<{\n  modelValue: string\n}>()\n\nconst emit = defineEmits<{\n  (e: 'update:modelValue', value: string): void\n}>()\n\nconst fileInput = ref<HTMLInputElement | null>(null)\n\nconst triggerFileInput = () => {\n  fileInput.value?.click()\n}\n\nconst handleFileUpload = (event: Event) => {\n  const target = event.target as HTMLInputElement\n  if (target.files && target.files[0]) {\n    const file = target.files[0]\n    const reader = new FileReader()\n    reader.onload = (e) => {\n      emit('update:modelValue', e.target?.result as string)\n    }\n    reader.readAsDataURL(file)\n  }\n}\n\nconst clearImage = () => {\n  emit('update:modelValue', '')\n  if (fileInput.value) {\n    fileInput.value.value = ''\n  }\n}\n</script>\n","<template>\n  <NumberField :id v-model=\"modelValue\" :min :max :step :disabled class=\"w-32\">\n    <NumberFieldDecrement />\n    <NumberFieldInput :aria-labelledby=\"ariaLabelledby\" />\n    <NumberFieldIncrement />\n  </NumberField>\n</template>\n\n<script setup lang=\"ts\">\nimport NumberField from '@/components/ui/number-field/NumberField.vue'\nimport NumberFieldDecrement from '@/components/ui/number-field/NumberFieldDecrement.vue'\nimport NumberFieldIncrement from '@/components/ui/number-field/NumberFieldIncrement.vue'\nimport NumberFieldInput from '@/components/ui/number-field/NumberFieldInput.vue'\n\ndefineProps<{\n  id?: string\n  min?: number\n  max?: number\n  step?: number\n  disabled?: boolean\n  ariaLabelledby?: string\n}>()\n\nconst modelValue = defineModel<number | null>()\n</script>\n","<template>\n  <NumberField :id v-model=\"modelValue\" :min :max :step :disabled class=\"w-32\">\n    <NumberFieldDecrement />\n    <NumberFieldInput :aria-labelledby=\"ariaLabelledby\" />\n    <NumberFieldIncrement />\n  </NumberField>\n</template>\n\n<script setup lang=\"ts\">\nimport NumberField from '@/components/ui/number-field/NumberField.vue'\nimport NumberFieldDecrement from '@/components/ui/number-field/NumberFieldDecrement.vue'\nimport NumberFieldIncrement from '@/components/ui/number-field/NumberFieldIncrement.vue'\nimport NumberFieldInput from '@/components/ui/number-field/NumberFieldInput.vue'\n\ndefineProps<{\n  id?: string\n  min?: number\n  max?: number\n  step?: number\n  disabled?: boolean\n  ariaLabelledby?: string\n}>()\n\nconst modelValue = defineModel<number | null>()\n</script>\n","<template>\n  <RadioGroup\n    v-model=\"modelValue\"\n    :name=\"id\"\n    orientation=\"horizontal\"\n    class=\"gap-4\"\n  >\n    <div\n      v-for=\"option in normalizedOptions\"\n      :key=\"option.value\"\n      class=\"flex items-center\"\n    >\n      <RadioGroupItem :id=\"`${id}-${option.value}`\" :value=\"option.value\" />\n      <label :for=\"`${id}-${option.value}`\" class=\"ml-2 cursor-pointer\">\n        {{ option.text }}\n      </label>\n    </div>\n  </RadioGroup>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport RadioGroup from '@/components/ui/radio-group/RadioGroup.vue'\nimport RadioGroupItem from '@/components/ui/radio-group/RadioGroupItem.vue'\nimport type { SettingOption } from '@/platform/settings/types'\n\nconst { options = [] } = defineProps<{\n  options?: (string | SettingOption)[]\n  id?: string\n}>()\n\nconst modelValue = defineModel<string | number | null>()\n\nconst normalizedOptions = computed(() =>\n  options.map((option) =>\n    typeof option === 'string'\n      ? { text: option, value: option }\n      : { text: option.text, value: option.value ?? option.text }\n  )\n)\n</script>\n","<template>\n  <RadioGroup\n    v-model=\"modelValue\"\n    :name=\"id\"\n    orientation=\"horizontal\"\n    class=\"gap-4\"\n  >\n    <div\n      v-for=\"option in normalizedOptions\"\n      :key=\"option.value\"\n      class=\"flex items-center\"\n    >\n      <RadioGroupItem :id=\"`${id}-${option.value}`\" :value=\"option.value\" />\n      <label :for=\"`${id}-${option.value}`\" class=\"ml-2 cursor-pointer\">\n        {{ option.text }}\n      </label>\n    </div>\n  </RadioGroup>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport RadioGroup from '@/components/ui/radio-group/RadioGroup.vue'\nimport RadioGroupItem from '@/components/ui/radio-group/RadioGroupItem.vue'\nimport type { SettingOption } from '@/platform/settings/types'\n\nconst { options = [] } = defineProps<{\n  options?: (string | SettingOption)[]\n  id?: string\n}>()\n\nconst modelValue = defineModel<string | number | null>()\n\nconst normalizedOptions = computed(() =>\n  options.map((option) =>\n    typeof option === 'string'\n      ? { text: option, value: option }\n      : { text: option.text, value: option.value ?? option.text }\n  )\n)\n</script>\n","<script setup lang=\"ts\">\nimport type { HTMLAttributes } from 'vue'\nimport { computed, useTemplateRef } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  min = 0,\n  max = 100,\n  step = 1,\n  disabled = false,\n  class: className\n} = defineProps<{\n  class?: HTMLAttributes['class']\n  disabled?: boolean\n  max?: number\n  min?: number\n  step?: number\n}>()\n\nconst modelValue = defineModel<number>({ required: true })\nconst root = useTemplateRef('root')\n\nconst progress = computed(() =>\n  max === min ? 0 : (modelValue.value - min) / (max - min)\n)\nconst dashOffset = computed(() => 75 * (1 - progress.value))\n\nfunction setValue(value: number) {\n  if (disabled) return\n  const stepped = step ? Math.round((value - min) / step) * step + min : value\n  modelValue.value = Math.min(max, Math.max(min, stepped))\n}\n\nfunction updateFromPointer(event: PointerEvent) {\n  const bounds = root.value?.getBoundingClientRect()\n  if (!bounds) return\n\n  const x = event.clientX - bounds.left - bounds.width / 2\n  const y = event.clientY - bounds.top - bounds.height / 2\n  const angle = (Math.atan2(y, x) * 180) / Math.PI\n  const clockwise = (angle + 225 + 360) % 360\n  const position = clockwise > 315 ? 0 : clockwise / 270\n  setValue(min + position * (max - min))\n}\n\nfunction onPointerDown(event: PointerEvent) {\n  root.value?.setPointerCapture(event.pointerId)\n  updateFromPointer(event)\n}\n\nfunction keyboardTarget(key: string): number | undefined {\n  switch (key) {\n    case 'ArrowUp':\n    case 'ArrowRight':\n      return modelValue.value + step\n    case 'ArrowDown':\n    case 'ArrowLeft':\n      return modelValue.value - step\n    case 'PageUp':\n      return modelValue.value + 10 * step\n    case 'PageDown':\n      return modelValue.value - 10 * step\n    case 'Home':\n      return min\n    case 'End':\n      return max\n  }\n}\n\nfunction onKeydown(event: KeyboardEvent) {\n  const target = keyboardTarget(event.key)\n  if (target === undefined) return\n  event.preventDefault()\n  setValue(target)\n}\n</script>\n\n<template>\n  <div\n    ref=\"root\"\n    role=\"slider\"\n    :tabindex=\"disabled ? -1 : 0\"\n    :aria-valuemin=\"min\"\n    :aria-valuemax=\"max\"\n    :aria-valuenow=\"modelValue\"\n    :aria-disabled=\"disabled || undefined\"\n    :class=\"\n      cn(\n        'size-12 cursor-pointer touch-none outline-none',\n        disabled && 'cursor-not-allowed opacity-50',\n        className\n      )\n    \"\n    @keydown=\"onKeydown\"\n    @pointerdown=\"onPointerDown\"\n    @pointermove=\"\n      (event) =>\n        root?.hasPointerCapture(event.pointerId) && updateFromPointer(event)\n    \"\n  >\n    <svg viewBox=\"0 0 32 32\" class=\"size-full rotate-[-225deg]\">\n      <circle\n        data-testid=\"knob-track\"\n        cx=\"16\"\n        cy=\"16\"\n        r=\"12\"\n        pathLength=\"100\"\n        fill=\"none\"\n        stroke=\"currentColor\"\n        stroke-width=\"3\"\n        stroke-dasharray=\"75 25\"\n        class=\"text-secondary-background\"\n      />\n      <circle\n        data-testid=\"knob-value\"\n        cx=\"16\"\n        cy=\"16\"\n        r=\"12\"\n        pathLength=\"100\"\n        fill=\"none\"\n        stroke=\"currentColor\"\n        stroke-width=\"3\"\n        stroke-linecap=\"round\"\n        stroke-dasharray=\"75 100\"\n        :stroke-dashoffset=\"dashOffset\"